/* ------------------------- utilitários ------------------------- */

const n2 = (x) =>
  x === null || x === undefined || Number.isNaN(x)
    ? "—"
    : Number(x).toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const somaNotas = (criterios, notas) =>
  criterios.reduce((t, c) => t + (notas[c.id] !== undefined ? c.valores[notas[c.id]] : 0), 0);

const maxFicha = (criterios) => criterios.reduce((t, c) => t + c.valores[3], 0);

const media = (a) => (a.length ? a.reduce((x, y) => x + y, 0) / a.length : null);

// "Ana Silva, Bruno Lima (6ºB)" -> [{nome:'Ana Silva',turma:<do trabalho>},{nome:'Bruno Lima',turma:'6ºB'}]
function listaIntegrantes(t) {
  return (t.integrantes || "")
    .split(/[,\/]+/)
    .map((x) => x.trim())
    .filter(Boolean)
    .map((x) => {
      const m = x.match(/^(.*?)[\s]*[([]([^)\]]+)[)\]][\s]*$/);
      return m
        ? { nome: m[1].trim(), turma: m[2].trim() }
        : { nome: x, turma: (t.turma || "").trim() };
    });
}

const mesmoNome = (a, b) => (a || "").trim().toLowerCase() === (b || "").trim().toLowerCase();

const ordenaPtBr = (a, b) => a.localeCompare(b, "pt-BR", { sensitivity: "base", numeric: true });

/* ================================ app ================================ */

export default function MostraJoaoPaulo() {
  const [aba, setAba] = useState("hig"); // hig | pdb | res
  const [etapa, setEtapa] = useState("pre"); // pre | projeto | apres
  const [trabalhos, setTrabalhos] = useState(TRABALHOS_EXEMPLO);
  const [avaliacoes, setAvaliacoes] = useState([]);
  const [avaliadores, setAvaliadores] = useState([]);
  const [avaliador, setAvaliador] = useState("");
  const [carregando, setCarregando] = useState(true);
  const [aviso, setAviso] = useState(null);
  const [erroRede, setErroRede] = useState(null);

  async function recarregar(silencioso) {
    if (!silencioso) setCarregando(true);
    try {
      const d = await api.carregar();
      setTrabalhos(d.trabalhos && d.trabalhos.length ? d.trabalhos : TRABALHOS_EXEMPLO);
      setAvaliadores(d.avaliadores || []);
      setAvaliacoes(d.avaliacoes || []);
      setErroRede(null);
    } catch (e) {
      setErroRede(
        e.message === "SEM_CONFIG"
          ? "O endereço do servidor ainda não foi configurado em config.js."
          : "Não foi possível falar com o servidor. Verifique a conexão e recarregue a página."
      );
    }
    setCarregando(false);
  }

  useEffect(() => {
    setAvaliador(local.get(CHAVE_AVALIADOR));
    recarregar();
  }, []);

  function guardarAvaliador(nome) {
    setAvaliador(nome);
    local.set(CHAVE_AVALIADOR, nome);
  }

  // o servidor grava com trava e já substitui avaliação anterior do mesmo
  // avaliador para o mesmo trabalho e etapa, devolvendo a lista atualizada
  async function enviarAvaliacao(registro) {
    try {
      const r = await api.enviarAvaliacao(registro);
      setAvaliacoes(r.avaliacoes || []);
      return true;
    } catch (e) {
      setAviso({ tipo: "erro", texto: "A avaliação não foi gravada. Tente enviar de novo." });
      return false;
    }
  }

  async function apagarAvaliacao(id) {
    try {
      const r = await api.apagarAvaliacao(id);
      setAvaliacoes(r.avaliacoes || []);
    } catch (e) {
      setAviso({ tipo: "erro", texto: "A avaliação não foi apagada. Tente de novo." });
    }
  }

  // sorteia os trabalhos de apresentação de cada avaliador cadastrado e
  // devolve os avisos (quem ficou com menos de 3, trabalhos sem avaliador)
  // para a tela de Resultados mostrar
  async function distribuirApresentacao() {
    try {
      const r = await api.distribuirApresentacao();
      setTrabalhos(r.trabalhos && r.trabalhos.length ? r.trabalhos : TRABALHOS_EXEMPLO);
      setAvaliadores(r.avaliadores || []);
      setAvaliacoes(r.avaliacoes || []);
      return { ok: true, avisos: r.avisos || [] };
    } catch (e) {
      return {
        ok: false,
        avisos: ["Não foi possível distribuir os avaliadores. Verifique a conexão e tente de novo."],
      };
    }
  }

  const abasTopo = [
    { id: "hig", nome: SEDES.hig.nome },
    { id: "pdb", nome: SEDES.pdb.nome },
    { id: "res", nome: "Resultados" },
  ];

  const sedeAtual = aba === "hig" || aba === "pdb" ? SEDES[aba].sede : null;
  const trabalhosDaSede = sedeAtual ? trabalhos.filter((t) => t.sede === sedeAtual) : trabalhos;

  return (
    <div className="pt">
      <style>{CSS}</style>

      <header className="pt-topo">
        <img src={LOGO} alt="Colégio João Paulo I" className="pt-logo" />
        <div className="pt-evento">
          <span className="pt-evento-nome">{EVENTO.nome}</span>
          <span className="pt-evento-sub">Avaliação dos trabalhos</span>
        </div>
      </header>

      <nav className="pt-abas">
        {abasTopo.map((a) => (
          <button
            key={a.id}
            className={"pt-aba" + (aba === a.id ? " ativa" : "")}
            onClick={() => setAba(a.id)}
          >
            {a.nome}
          </button>
        ))}
      </nav>

      {(aba === "hig" || aba === "pdb") && (
        <nav className="pt-subabas">
          {ORDEM_ETAPAS.map((id) => (
            <button
              key={id}
              className={"pt-subaba" + (etapa === id ? " ativa" : "")}
              onClick={() => setEtapa(id)}
            >
              {ETAPAS[id].nome}
            </button>
          ))}
        </nav>
      )}

      {erroRede && <div className="pt-aviso erro">{erroRede}</div>}

      {aviso && (
        <div className={"pt-aviso " + aviso.tipo} onClick={() => setAviso(null)}>
          {aviso.texto}
          <span className="pt-fechar">fechar</span>
        </div>
      )}

      <main className="pt-palco">
        {carregando ? (
          <div className="pt-cartao">
            <p className="pt-vazio">Carregando…</p>
          </div>
        ) : aba === "res" ? (
          <Resultados
            trabalhos={trabalhos}
            avaliacoes={avaliacoes}
            avaliadores={avaliadores}
            onAtualizar={() => recarregar(true)}
            onApagar={apagarAvaliacao}
            onDistribuir={distribuirApresentacao}
          />
        ) : (
          <Ficha
            key={aba + ":" + etapa}
            etapa={ETAPAS[etapa]}
            sede={sedeAtual}
            trabalhos={trabalhosDaSede}
            avaliacoes={avaliacoes}
            avaliadores={avaliadores}
            avaliador={avaliador}
            setAvaliador={guardarAvaliador}
            onEnviar={enviarAvaliacao}
          />
        )}
      </main>

      <footer className="pt-rodape">
        Colégio João Paulo I · {EVENTO.nome} · uso interno dos avaliadores
      </footer>
    </div>
  );
}

/* =============================== ficha =============================== */

function Ficha({ etapa, sede, trabalhos, avaliacoes, avaliadores, avaliador, setAvaliador, onEnviar }) {
  const [numero, setNumero] = useState("");
  const [notas, setNotas] = useState({});
  const [comentario, setComentario] = useState("");
  const [destaque, setDestaque] = useState(null);
  const [zerado, setZerado] = useState(false);
  const [tela, setTela] = useState("form"); // form | revisao | enviado
  const [erro, setErro] = useState("");
  const [enviando, setEnviando] = useState(false);

  const criterios = etapa.criterios;
  const temDestaque = etapa.id === "apres";

  const cadastro = avaliadores.find((a) => mesmoNome(a.nome, avaliador));
  const semCadastro = avaliadores.length === 0;
  const atribuidosGlobal = cadastro ? cadastro[etapa.id] || [] : [];
  // a atribuição vem em números globais (com o prefixo da sede); aqui já
  // cruzamos com os trabalhos desta sede, então o filtro por sede acontece
  // naturalmente
  const numerosDaSede = new Set(trabalhos.map((t) => t.num));
  const atribuidos = atribuidosGlobal.filter((n) => numerosDaSede.has(n));
  // sem cadastro de avaliadores, a lista fica aberta (modo de contingência)
  const listaTrabalhos = semCadastro ? trabalhos : trabalhos.filter((t) => atribuidos.includes(t.num));

  const trabalho = listaTrabalhos.find((t) => t.num === numero);
  const total = somaNotas(criterios, notas);
  const maximo = maxFicha(criterios);
  const preenchidos = criterios.filter((c) => notas[c.id] !== undefined).length;

  useEffect(() => {
    if (numero && !listaTrabalhos.some((t) => t.num === numero)) {
      setNumero("");
      setNotas({});
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [avaliador, sede]);

  const feitos = listaTrabalhos.filter((t) =>
    avaliacoes.some(
      (a) => a.etapa === etapa.id && a.trabalho === t.num && mesmoNome(a.avaliador, avaliador)
    )
  ).length;

  const jaAvaliou = avaliacoes.find(
    (a) =>
      a.etapa === etapa.id &&
      a.trabalho === numero &&
      mesmoNome(a.avaliador, avaliador) &&
      avaliador.trim() !== ""
  );

  function limpar() {
    setNumero("");
    setNotas({});
    setComentario("");
    setDestaque(null);
    setZerado(false);
    setTela("form");
    setErro("");
  }

  function revisar() {
    if (!avaliador.trim()) return setErro("Selecione seu nome antes de enviar.");
    if (!numero) return setErro("Escolha o número do trabalho.");
    if (zerado) {
      if (!comentario.trim())
        return setErro("Explique o motivo da nota zero no campo de comentários.");
    } else {
      if (preenchidos < criterios.length)
        return setErro("Faltam " + (criterios.length - preenchidos) + " critério(s) sem nota.");
      if (temDestaque && destaque === null) return setErro("Indique se o trabalho merece destaque.");
    }
    setErro("");
    setTela("revisao");
  }

  async function confirmar() {
    setEnviando(true);
    const ok = await onEnviar({
      id: "av" + Date.now() + Math.floor(Math.random() * 999),
      sede: trabalho ? trabalho.sede : sede,
      etapa: etapa.id,
      trabalho: numero,
      avaliador: avaliador.trim(),
      notas: zerado ? {} : notas,
      total: zerado ? 0 : total,
      zerado,
      comentario: comentario.trim(),
      destaque: zerado ? false : temDestaque ? destaque : false,
      em: new Date().toISOString(),
    });
    setEnviando(false);
    if (ok) setTela("enviado");
  }

  if (tela === "enviado")
    return (
      <div className="pt-cartao pt-final">
        <div className="pt-selo">✓</div>
        <h2>Avaliação enviada</h2>
        <p>
          {etapa.nome} · trabalho {numero} — {trabalho?.titulo}
        </p>
        <div className="pt-nota-final">
          <span>{n2(zerado ? 0 : total)}</span>
          <em>de {n2(maximo)}</em>
        </div>
        {zerado && <p className="pt-zero-msg">Nota zerada (entrega parcial ou ausência).</p>}
        {!zerado && destaque && <p className="pt-destaque-msg">Indicado para destaque da Mostra.</p>}
        <button className="pt-btn" onClick={limpar}>
          Avaliar outro trabalho
        </button>
      </div>
    );

  if (tela === "revisao")
    return (
      <div className="pt-cartao">
        <span className="pt-etiqueta">Confirme antes de enviar</span>
        <h2 className="pt-h2">{etapa.nome}</h2>
        <div className="pt-ficha-trabalho">
          <strong>
            {trabalho?.num} — {trabalho?.titulo}
          </strong>
          <span>
            {trabalho?.turma}
            {trabalho?.orientador ? " · orientação de " + trabalho.orientador : ""}
          </span>
          <span>{trabalho?.integrantes}</span>
          <span>Avaliador(a): {avaliador}</span>
        </div>

        {zerado ? (
          <div className="pt-rev-bloco">
            <span className="pt-rotulo">Nota desta etapa</span>
            <p className="pt-zero-msg">0,00 — nota zerada pelo avaliador (entrega parcial ou ausência).</p>
          </div>
        ) : (
          <ul className="pt-revisao">
            {criterios.map((c) => (
              <li key={c.id}>
                <span className="pt-rev-nome">{c.nome}</span>
                <span className={"pt-nivel n" + notas[c.id]}>{NIVEIS[notas[c.id]]}</span>
                <span className="pt-rev-nota">{n2(c.valores[notas[c.id]])}</span>
              </li>
            ))}
            <li className="pt-rev-total">
              <span className="pt-rev-nome">Total da ficha</span>
              <span />
              <span className="pt-rev-nota">{n2(total)}</span>
            </li>
          </ul>
        )}

        {!zerado && temDestaque && (
          <div className="pt-rev-bloco">
            <span className="pt-rotulo">Destaque da Mostra</span>
            <p>{destaque ? "Sim — indicado para premiação" : "Não indicado"}</p>
          </div>
        )}
        <div className="pt-rev-bloco">
          <span className="pt-rotulo">Comentários{zerado ? " (motivo da nota zero)" : ""}</span>
          <p>{comentario.trim() || "(sem comentários)"}</p>
        </div>

        {jaAvaliou && (
          <p className="pt-alerta">
            Você já enviou uma avaliação deste trabalho nesta etapa. Confirmar substitui a anterior.
          </p>
        )}

        <div className="pt-acoes">
          <button className="pt-btn vazado" onClick={() => setTela("form")}>
            Voltar e corrigir
          </button>
          <button className="pt-btn" onClick={confirmar} disabled={enviando}>
            {enviando ? "Enviando…" : "Confirmar e enviar avaliação"}
          </button>
        </div>
      </div>
    );

  return (
    <div className="pt-cartao">
      <span className="pt-etiqueta">Ficha de avaliação</span>
      <h2 className="pt-h2">{etapa.nome}</h2>
      <p className="pt-legenda">
        Pontuação máxima {n2(maximo)}. Quando o desempenho estiver entre dois níveis, escolha o mais
        próximo.
      </p>

      <div className="pt-cabecalho-ficha">
        <div className="pt-campo">
          <label className="pt-rotulo">Avaliador(a)</label>
          {semCadastro ? (
            <input
              className="pt-entrada"
              placeholder="Seu nome"
              value={avaliador}
              onChange={(e) => setAvaliador(e.target.value)}
            />
          ) : (
            <select
              className="pt-entrada"
              value={cadastro ? cadastro.nome : ""}
              onChange={(e) => setAvaliador(e.target.value)}
            >
              <option value="">Selecione seu nome…</option>
              {avaliadores.map((a) => (
                <option key={a.nome} value={a.nome}>
                  {a.nome}
                </option>
              ))}
            </select>
          )}
        </div>
        <div className="pt-campo">
          <label className="pt-rotulo">Número do trabalho</label>
          <select
            className="pt-entrada"
            value={numero}
            onChange={(e) => setNumero(e.target.value)}
            disabled={!semCadastro && !cadastro}
          >
            <option value="">
              {!semCadastro && !cadastro ? "Selecione seu nome primeiro" : "Selecione…"}
            </option>
            {listaTrabalhos.map((t) => (
              <option key={t.num} value={t.num}>
                {t.num} — {t.titulo}
              </option>
            ))}
          </select>
        </div>
      </div>

      {cadastro && (
        <div className="pt-atribuicao">
          {listaTrabalhos.length === 0 ? (
            <span>
              {atribuidosGlobal.length > numerosDaSede.size
                ? "Você não avalia esta etapa nesta sede — confira se selecionou a unidade certa."
                : "Nenhum trabalho foi atribuído a você nesta etapa. Procure a coordenação."}
            </span>
          ) : (
            <>
              <span>
                <strong>{feitos}</strong> de <strong>{listaTrabalhos.length}</strong> trabalhos
                avaliados nesta etapa
              </span>
              <div className="pt-fichas-mini">
                {listaTrabalhos.map((t) => {
                  const ok = avaliacoes.some(
                    (a) =>
                      a.etapa === etapa.id && a.trabalho === t.num && mesmoNome(a.avaliador, avaliador)
                  );
                  return (
                    <button
                      key={t.num}
                      className={"pt-mini" + (ok ? " ok" : "") + (numero === t.num ? " atual" : "")}
                      onClick={() => setNumero(t.num)}
                      title={t.titulo}
                    >
                      {t.num}
                    </button>
                  );
                })}
              </div>
            </>
          )}
        </div>
      )}

      {trabalho && (
        <div className="pt-ficha-trabalho destaque-borda">
          <strong>{trabalho.titulo}</strong>
          <span className="pt-turma">{trabalho.turma}</span>
          {trabalho.orientador && <span>Orientador(a): {trabalho.orientador}</span>}
          <span>{trabalho.integrantes}</span>
          {jaAvaliou && (
            <span className="pt-tag">
              Você já avaliou este trabalho nesta etapa — enviar de novo substitui a nota anterior.
            </span>
          )}
        </div>
      )}

      <div className="pt-zero-caixa">
        <label className="pt-zero-opcao">
          <input
            type="checkbox"
            checked={zerado}
            onChange={(e) => setZerado(e.target.checked)}
          />
          <span>Atribuir nota zero nesta etapa (entrega parcial ou ausência)</span>
        </label>
        {zerado && (
          <p className="pt-legenda">
            Os critérios abaixo deixam de valer para esta ficha e a nota desta etapa, para este
            avaliador, será 0,00. Explique o motivo no campo de comentários — é obrigatório quando a
            nota é zerada.
          </p>
        )}
      </div>

      <div className={"pt-criterios" + (zerado ? " pt-desabilitado" : "")}>
        {criterios.map((c, i) => (
          <section key={c.id} className="pt-criterio">
            <header>
              <span className="pt-num">{String(i + 1).padStart(2, "0")}</span>
              <h3>{c.nome}</h3>
              <span className="pt-max">máx. {n2(c.valores[3])}</span>
            </header>
            <div className="pt-niveis">
              {NIVEIS.map((nome, k) => (
                <button
                  key={nome}
                  className={"pt-nivel-cartao n" + k + (notas[c.id] === k ? " marcado" : "")}
                  onClick={() => setNotas((s) => ({ ...s, [c.id]: k }))}
                >
                  <span className="pt-nivel-topo">
                    <span className="pt-nivel-nome">{nome}</span>
                    <span className="pt-nivel-pts">{n2(c.valores[k])}</span>
                  </span>
                  <span className="pt-passos">
                    {[0, 1, 2, 3].map((s) => (
                      <i key={s} className={s <= k ? "cheio" : ""} />
                    ))}
                  </span>
                  <span className="pt-nivel-desc">{c.desc[k]}</span>
                </button>
              ))}
            </div>
          </section>
        ))}
      </div>

      {temDestaque && !zerado && (
        <section className="pt-criterio">
          <header>
            <span className="pt-num">★</span>
            <h3>Diferencial e impacto</h3>
            <span className="pt-max">não pontuado</span>
          </header>
          <p className="pt-legenda">
            O trabalho se destaca dos demais de maneira positiva — pela inovação, pelo impacto social
            do tema, pela qualidade da execução ou pela atratividade da apresentação? A indicação não
            altera a nota; quando houver consenso entre os avaliadores da apresentação, o trabalho
            aparece nos resultados como premiado.
          </p>
          <div className="pt-sim-nao">
            <button
              className={"pt-btn-escolha" + (destaque === true ? " sim" : "")}
              onClick={() => setDestaque(true)}
            >
              Sim, indico para destaque
            </button>
            <button
              className={"pt-btn-escolha" + (destaque === false ? " nao" : "")}
              onClick={() => setDestaque(false)}
            >
              Não
            </button>
          </div>
        </section>
      )}

      <div className="pt-campo">
        <label className="pt-rotulo">
          {etapa.id === "apres" ? "Comentários gerais sobre a apresentação" : "Comentários e orientações para a próxima etapa"}
        </label>
        <textarea
          className="pt-entrada"
          rows={4}
          value={comentario}
          onChange={(e) => setComentario(e.target.value)}
          placeholder="Feedback claro e construtivo para o grupo."
        />
      </div>

      {erro && <p className="pt-alerta">{erro}</p>}

      <div className="pt-barra">
        <div className="pt-barra-info">
          {zerado ? (
            <span className="pt-zero-msg">Nota desta etapa: 0,00 (zerada)</span>
          ) : (
            <>
              <div className="pt-barra-numeros">
                <strong>{n2(total)}</strong>
                <span>/ {n2(maximo)}</span>
              </div>
              <span className="pt-barra-passo">
                {preenchidos} de {criterios.length} critérios
              </span>
              <div className="pt-trilho">
                <div
                  className="pt-preenchimento"
                  style={{ width: (preenchidos / criterios.length) * 100 + "%" }}
                />
              </div>
            </>
          )}
        </div>
        <button className="pt-btn" onClick={revisar}>
          Revisar e enviar
        </button>
      </div>
    </div>
  );
}

/* ============================= resultados ============================= */

function Resultados({ trabalhos, avaliacoes, avaliadores, onAtualizar, onApagar, onDistribuir }) {
  const [codigo, setCodigo] = useState("");
  const [liberado, setLiberado] = useState(false);
  const [aberto, setAberto] = useState(null);
  const [regra, setRegra] = useState("unanime");
  const [filtroSede, setFiltroSede] = useState("todas");
  const [painel, setPainel] = useState(null); // null | "trabalhos" | "avaliadores"
  const [confirmandoDistribuicao, setConfirmandoDistribuicao] = useState(false);
  const [distribuindo, setDistribuindo] = useState(false);
  const [avisosDistribuicao, setAvisosDistribuicao] = useState(null);

  async function executarDistribuicao() {
    setDistribuindo(true);
    const r = await onDistribuir();
    setDistribuindo(false);
    setConfirmandoDistribuicao(false);
    setAvisosDistribuicao(r.avisos || []);
  }

  const linhas = useMemo(() => {
    return trabalhos.map((t) => {
      const dados = {};
      ORDEM_ETAPAS.forEach((e) => {
        const lista = avaliacoes.filter((a) => a.trabalho === t.num && a.etapa === e);
        dados[e] = {
          lista,
          n: lista.length,
          media: media(lista.map((a) => a.total)),
          destaques: lista.filter((a) => a.destaque).length,
        };
      });
      const avalDestaque = dados.apres.n;
      const sim = dados.apres.destaques;
      const consenso =
        avalDestaque >= 2 && (regra === "unanime" ? sim === avalDestaque : sim > avalDestaque / 2);
      return { ...t, ...dados, avalDestaque, sim, consenso };
    });
  }, [trabalhos, avaliacoes, regra]);

  const linhasFiltradas =
    filtroSede === "todas" ? linhas : linhas.filter((l) => l.sede === SEDES[filtroSede].sede);

  const premiados = linhasFiltradas.filter((l) => l.consenso);
  const numerosValidos = new Set(trabalhos.map((t) => t.num));

  function baixaArquivo(cab, corpo, nome) {
    const esc = (v) => `"${String(v).replace(/"/g, '""')}"`;
    const csv = [cab, ...corpo].map((r) => r.map(esc).join(";")).join("\r\n");
    const blob = new Blob(["﻿" + csv], { type: "text/csv;charset=utf-8;" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = nome;
    a.click();
    URL.revokeObjectURL(a.href);
  }

  function baixarCSVAlunos() {
    const cab = [
      "Sede", "Turma", "Aluno", "Nº do trabalho", "Trabalho", "Orientador",
      "Média pré-projeto", "Média projeto", "Média apresentação", "Prêmio",
    ];
    const alunos = [];
    linhasFiltradas.forEach((l) => {
      listaIntegrantes(l).forEach((i) => {
        alunos.push({ turma: i.turma, nome: i.nome, linha: l });
      });
    });
    alunos.sort((a, b) => ordenaPtBr(a.turma, b.turma) || ordenaPtBr(a.nome, b.nome));
    const corpo = alunos.map(({ turma, nome, linha: l }) => [
      l.sede, turma, nome, l.num, l.titulo, l.orientador || "",
      l.pre.media === null ? "" : n2(l.pre.media),
      l.projeto.media === null ? "" : n2(l.projeto.media),
      l.apres.media === null ? "" : n2(l.apres.media),
      l.consenso ? "SIM" : "",
    ]);
    baixaArquivo(cab, corpo, "mostra-joao-paulo-notas-por-aluno.csv");
  }

  function baixarCSV() {
    const cab = [
      "Nº", "Trabalho", "Sede", "Turma", "Área", "Orientador", "Integrantes",
      "Avaliações pré-projeto", "Média pré-projeto",
      "Avaliações projeto", "Média projeto",
      "Avaliações apresentação", "Média apresentação",
      "Indicações de destaque", "Prêmio",
    ];
    const corpo = linhasFiltradas.map((l) => [
      l.num, l.titulo, l.sede, l.turma, l.area || "", l.orientador || "", l.integrantes,
      l.pre.n, l.pre.media === null ? "" : n2(l.pre.media),
      l.projeto.n, l.projeto.media === null ? "" : n2(l.projeto.media),
      l.apres.n, l.apres.media === null ? "" : n2(l.apres.media),
      l.avalDestaque ? l.sim + " de " + l.avalDestaque : "",
      l.consenso ? "SIM" : "",
    ]);
    baixaArquivo(cab, corpo, "mostra-joao-paulo-por-trabalho.csv");
  }

  if (!liberado)
    return (
      <div className="pt-cartao pt-final">
        <h2>Área da coordenação</h2>
        <p>Os resultados consolidados das duas sedes ficam nesta aba. Informe o código de acesso.</p>
        <input
          className="pt-entrada estreita"
          type="password"
          value={codigo}
          placeholder="Código"
          onChange={(e) => setCodigo(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && setLiberado(codigo === CODIGO_RESULTADOS)}
        />
        <button className="pt-btn" onClick={() => setLiberado(codigo === CODIGO_RESULTADOS)}>
          Entrar
        </button>
        {codigo && codigo !== CODIGO_RESULTADOS && <p className="pt-alerta">Código incorreto.</p>}
      </div>
    );

  return (
    <div className="pt-cartao">
      <div className="pt-linha-topo">
        <div>
          <span className="pt-etiqueta">Consolidado</span>
          <h2 className="pt-h2">Resultados da Mostra</h2>
        </div>
        <div className="pt-controles">
          <select
            className="pt-select"
            value={filtroSede}
            onChange={(e) => setFiltroSede(e.target.value)}
          >
            <option value="todas">Todas as sedes</option>
            <option value="hig">{SEDES.hig.nome}</option>
            <option value="pdb">{SEDES.pdb.nome}</option>
          </select>
          <select className="pt-select" value={regra} onChange={(e) => setRegra(e.target.value)}>
            <option value="unanime">Prêmio por unanimidade</option>
            <option value="maioria">Prêmio por maioria</option>
          </select>
          <button className="pt-btn fino" onClick={onAtualizar}>
            Atualizar
          </button>
          <button className="pt-btn fino" onClick={baixarCSVAlunos}>
            CSV por aluno
          </button>
          <button className="pt-btn fino" onClick={baixarCSV}>
            CSV por trabalho
          </button>
          <button
            className={"pt-btn fino" + (painel === "trabalhos" ? " ligado" : "")}
            onClick={() => setPainel(painel === "trabalhos" ? null : "trabalhos")}
          >
            Trabalhos
          </button>
          <button
            className={"pt-btn fino" + (painel === "avaliadores" ? " ligado" : "")}
            onClick={() => setPainel(painel === "avaliadores" ? null : "avaliadores")}
          >
            Avaliadores
          </button>
          {!confirmandoDistribuicao ? (
            <button className="pt-btn fino" onClick={() => setConfirmandoDistribuicao(true)}>
              Distribuir avaliadores
            </button>
          ) : (
            <span className="pt-confirmar-distribuicao">
              <span>Sortear de novo substitui a distribuição atual. Confirma?</span>
              <button className="pt-btn fino" onClick={executarDistribuicao} disabled={distribuindo}>
                {distribuindo ? "Distribuindo…" : "Sim, distribuir"}
              </button>
              <button
                className="pt-btn fino vazado"
                onClick={() => setConfirmandoDistribuicao(false)}
                disabled={distribuindo}
              >
                Cancelar
              </button>
            </span>
          )}
        </div>
      </div>

      {avisosDistribuicao && (
        <div className="pt-cadastro">
          <p className="pt-legenda" style={{ margin: 0 }}>
            {avisosDistribuicao.length === 0
              ? "Distribuição concluída sem pendências: todo avaliador elegível recebeu 3 trabalhos e todo trabalho recebeu ao menos um avaliador de apresentação."
              : "Distribuição concluída com avisos:"}
          </p>
          {avisosDistribuicao.map((a, i) => (
            <p key={i} className="pt-alerta" style={{ margin: 0 }}>
              {a}
            </p>
          ))}
        </div>
      )}

      {painel === "trabalhos" && (
        <div className="pt-cadastro">
          <p className="pt-legenda">
            Os trabalhos vêm da aba <code>trabalhos</code> da planilha. Edite lá e clique em Atualizar
            aqui — não há nada a cadastrar por esta tela. São {trabalhos.length} trabalhos carregados
            nas duas sedes.
          </p>
          <div className="pt-tabela-rolagem">
            <table className="pt-tabela compacta">
              <thead>
                <tr>
                  <th>Nº</th>
                  <th>Título</th>
                  <th>Sede</th>
                  <th>Turma</th>
                  <th>Área</th>
                  <th>Orientador</th>
                </tr>
              </thead>
              <tbody>
                {trabalhos.map((t) => (
                  <tr key={t.num}>
                    <td className="mono">{t.num}</td>
                    <td>{t.titulo}</td>
                    <td className="fraco">{t.sede}</td>
                    <td className="fraco">{t.turma}</td>
                    <td className="fraco">{t.area || "—"}</td>
                    <td className="fraco">{t.orientador || "—"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {painel === "avaliadores" && (
        <div className="pt-cadastro">
          <p className="pt-legenda">
            Os avaliadores da apresentação vêm da aba <code>avaliadores</code> da planilha (nome, sede,
            área e séries que a pessoa pode avaliar). O botão "Distribuir avaliadores" sorteia 3
            trabalhos para cada um, respeitando essas colunas — ninguém avalia o que orienta. As
            colunas do pré-projeto e do projeto são montadas sozinhas a partir de quem orienta cada
            trabalho. Edite a planilha e clique em Atualizar.
          </p>

          {avaliadores.length > 0 && (
            <div className="pt-tabela-rolagem">
              <table className="pt-tabela compacta">
                <thead>
                  <tr>
                    <th>Avaliador(a)</th>
                    <th>Área</th>
                    <th>Séries</th>
                    <th>Pré-projeto</th>
                    <th>Projeto</th>
                    <th>Apresentação</th>
                    <th className="dir">Concluído</th>
                  </tr>
                </thead>
                <tbody>
                  {avaliadores.map((a) => {
                    const conta = (etapa) =>
                      (a[etapa] || []).filter((num) =>
                        avaliacoes.some(
                          (x) => x.etapa === etapa && x.trabalho === num && mesmoNome(x.avaliador, a.nome)
                        )
                      ).length;
                    const totalAtrib =
                      (a.pre || []).length + (a.projeto || []).length + (a.apres || []).length;
                    const totalFeito = conta("pre") + conta("projeto") + conta("apres");
                    const invalidos = [
                      ...(a.pre || []),
                      ...(a.projeto || []),
                      ...(a.apres || []),
                    ].filter((n) => !numerosValidos.has(n));
                    return (
                      <tr key={a.nome}>
                        <td>
                          {a.nome}
                          {invalidos.length > 0 && (
                            <span className="pt-invalido">
                              números sem trabalho: {[...new Set(invalidos)].join(", ")}
                            </span>
                          )}
                        </td>
                        <td className="fraco">{(a.area || []).join(", ") || "qualquer"}</td>
                        <td className="fraco">{(a.series || []).join(", ") || "qualquer"}</td>
                        <td className="mono fraco">
                          {(a.pre || []).join(", ") || "—"} <em>({conta("pre")}/{(a.pre || []).length})</em>
                        </td>
                        <td className="mono fraco">
                          {(a.projeto || []).join(", ") || "—"}{" "}
                          <em>
                            ({conta("projeto")}/{(a.projeto || []).length})
                          </em>
                        </td>
                        <td className="mono fraco">
                          {(a.apres || []).join(", ") || "—"} <em>({conta("apres")}/{(a.apres || []).length})</em>
                        </td>
                        <td className="dir mono">
                          <span
                            className={
                              "pt-selo-mini" + (totalAtrib && totalFeito === totalAtrib ? " completo" : "")
                            }
                          >
                            {totalFeito}/{totalAtrib}
                          </span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {premiados.length > 0 && (
        <div className="pt-premios">
          <span className="pt-rotulo">Destaques com consenso dos avaliadores</span>
          {premiados.map((p) => (
            <div key={p.num} className="pt-premio">
              <span className="pt-medalha">★</span>
              <div>
                <strong>
                  {p.num} — {p.titulo}
                </strong>
                <span>
                  {p.sede} · {p.turma} · {p.sim} de {p.avalDestaque} avaliadores da apresentação
                  indicaram
                </span>
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="pt-tabela-rolagem">
        <table className="pt-tabela">
          <thead>
            <tr>
              <th>Nº</th>
              <th>Trabalho</th>
              <th>Sede</th>
              <th>Turma</th>
              <th>Orientador</th>
              <th className="dir">Pré-projeto</th>
              <th className="dir">Projeto</th>
              <th className="dir">Apresentação</th>
              <th className="dir">Destaque</th>
            </tr>
          </thead>
          <tbody>
            {linhasFiltradas.map((l) => (
              <tr
                key={l.num}
                onClick={() => setAberto(aberto === l.num ? null : l.num)}
                className={aberto === l.num ? "aberta" : ""}
              >
                <td className="mono">{l.num}</td>
                <td className="titulo">{l.titulo}</td>
                <td className="fraco">{l.sede}</td>
                <td className="fraco">{l.turma}</td>
                <td className="fraco">{l.orientador || "—"}</td>
                <td className="dir mono">
                  {n2(l.pre.media)} <em>({l.pre.n})</em>
                </td>
                <td className="dir mono">
                  {n2(l.projeto.media)} <em>({l.projeto.n})</em>
                </td>
                <td className="dir mono">
                  {n2(l.apres.media)} <em>({l.apres.n})</em>
                </td>
                <td className="dir mono">
                  {l.consenso ? <span className="pt-medalha peq">★</span> : null}
                  {l.avalDestaque ? l.sim + "/" + l.avalDestaque : "—"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {aberto && <Detalhe linha={linhasFiltradas.find((l) => l.num === aberto)} onApagar={onApagar} />}

      <p className="pt-legenda rodape">
        Cada etapa (pré-projeto, projeto e apresentação) vale 1,00 e é calculada separadamente: quando
        há mais de um avaliador, a nota da etapa é a média entre eles. As três etapas não são somadas
        entre si. A indicação de destaque é feita apenas na ficha da apresentação, e o prêmio aparece
        quando há consenso entre os avaliadores dessa etapa. Clique em uma linha para ver as notas por
        critério e os comentários.
      </p>
    </div>
  );
}

function Detalhe({ linha, onApagar }) {
  if (!linha) return null;
  return (
    <div className="pt-detalhe">
      <h3>
        {linha.num} — {linha.titulo}
      </h3>
      <p className="pt-legenda">
        {linha.sede} · {linha.turma}
        {linha.orientador ? " · orientação de " + linha.orientador : ""} · {linha.integrantes}
      </p>

      {ORDEM_ETAPAS.map((e) => {
        const etapa = ETAPAS[e];
        const dados = linha[e];
        if (!dados.n)
          return (
            <div key={e} className="pt-etapa-bloco">
              <span className="pt-rotulo">{etapa.nome}</span>
              <p className="pt-vazio">Sem avaliações registradas.</p>
            </div>
          );
        return (
          <div key={e} className="pt-etapa-bloco">
            <span className="pt-rotulo">
              {etapa.nome} · {dados.n} avaliação(ões) · média {n2(dados.media)}
            </span>
            <table className="pt-tabela compacta">
              <thead>
                <tr>
                  <th>Critério</th>
                  {dados.lista.map((a) => (
                    <th key={a.id} className="dir">
                      {a.avaliador.split(" ")[0]}
                    </th>
                  ))}
                  <th className="dir">Média</th>
                </tr>
              </thead>
              <tbody>
                {etapa.criterios.map((c) => {
                  const vals = dados.lista.map((a) =>
                    a.zerado || a.notas[c.id] === undefined ? null : c.valores[a.notas[c.id]]
                  );
                  const validos = vals.filter((v) => v !== null);
                  return (
                    <tr key={c.id}>
                      <td>{c.nome}</td>
                      {dados.lista.map((a, i) => (
                        <td key={a.id} className="dir mono">
                          {a.zerado ? <span className="pt-zero-mini">zerado</span> : n2(vals[i])}
                        </td>
                      ))}
                      <td className="dir mono forte">{n2(media(validos))}</td>
                    </tr>
                  );
                })}
                <tr className="total">
                  <td>Total</td>
                  {dados.lista.map((a) => (
                    <td key={a.id} className="dir mono">
                      {a.zerado ? <span className="pt-zero-mini">0,00 (zerado)</span> : n2(a.total)}
                    </td>
                  ))}
                  <td className="dir mono forte">{n2(dados.media)}</td>
                </tr>
              </tbody>
            </table>

            <div className="pt-comentarios">
              {dados.lista.map((a) => (
                <div key={a.id} className="pt-comentario">
                  <div className="pt-com-topo">
                    <strong>{a.avaliador}</strong>
                    {a.destaque && <span className="pt-tag-destaque">indicou destaque</span>}
                    {a.zerado && <span className="pt-tag-zero">nota zero</span>}
                    <button className="pt-x" onClick={() => onApagar(a.id)} title="Apagar avaliação">
                      ×
                    </button>
                  </div>
                  <p>{a.comentario || "(sem comentários)"}</p>
                </div>
              ))}
            </div>
          </div>
        );
      })}
    </div>
  );
}

/* ================================ css ================================ */

